using UnityEngine;using LWS.TruckCheeseRolling;
namespace LWS.TruckMattressRacing {public sealed class MattressObstacle:MonoBehaviour {
 public MattressWorld world;public MattressObstacleKind kind;public Rigidbody body;public Collider shape;public CheeseTree tree;public bool Fired{get;private set;}FixedJoint root;float knocked=-1;
 public void ResetObstacle(Vector3 p,Quaternion q){transform.localScale=Vector3.one;Fired=false;knocked=-1;body.isKinematic=false;body.detectCollisions=true;body.position=p;body.rotation=q;transform.SetPositionAndRotation(p,q);body.linearVelocity=body.angularVelocity=Vector3.zero;shape.enabled=true;if(tree!=null)tree.ResetTree(p,q);if(kind==MattressObstacleKind.Sheep)body.isKinematic=true;if(kind==MattressObstacleKind.Fence){if(root!=null)Destroy(root);root=gameObject.AddComponent<FixedJoint>();root.autoConfigureConnectedAnchor=false;root.connectedAnchor=p;root.breakForce=500;root.breakTorque=300;}}
 void OnTriggerEnter(Collider other){if(kind!=MattressObstacleKind.Sheep||Fired||!world.match.Live||world.match.Phase!=MattressPhase.Race)return;var r=other.GetComponentInParent<MattressRacer>();if(r==null||r.Phase!=MattressAttempt.Racing)return;Fired=true;shape.enabled=false;world.Explode(transform.position);transform.localScale=Vector3.zero;}
 void OnJointBreak(float value){knocked=Time.time;root=null;}public void Maintain(){if(tree!=null&&tree.KnockedDown&&knocked<0)knocked=Time.time;if(knocked>=0&&Time.time-knocked>6){shape.enabled=false;body.detectCollisions=false;}if(body.position.y<world.match.course.Height(body.position)-12){body.isKinematic=true;shape.enabled=false;transform.localScale=Vector3.zero;}}
}}
